/* @autogenerated */
import { Directive, TemplateRef, viewChild } from '@angular/core';
import { ImportDefinition } from '@shared/toolkit/entity-import/entity-import.model';
import { actionRoles } from './action-roles';
import { BaseAction } from './base-action';

/**
 * Acción de importación desde Excel: no es contextual y su plantilla `#importTemplate` muestra
 * `<entity-import [definition]="definition" (closed)="close()" />`.
 *
 * Visible si el ACL genérico permite `create` o `update` (cada fila se crea o se actualiza según exista) y el usuario
 * tiene alguno de los roles de `actions.import` en la configuración.
 */
@Directive()
export abstract class BaseImportAction<T> extends BaseAction<T> {
  readonly name = 'import';
  override readonly contextual = false;
  override readonly render = viewChild<TemplateRef<any>>('importTemplate');

  abstract readonly definition: ImportDefinition<T>;

  private readonly rolesAllow = actionRoles('import', () => this.definition.storageKey);

  run(): void {
    // La pantalla muestra la importación en curso, si la hay, o pide el fichero
  }

  close(): void {
    this.container()?.close();
  }

  protected override allowed(name?: string): boolean {
    return name ? super.allowed(name) : (super.allowed('create') || super.allowed('update')) && this.rolesAllow();
  }
}
